function W.ldMod(pk)
if type(pk)~=WBd[1712]then
return nil
end
local qk={weak={},strong={},res={}}
for rk,sk in pairs(type(pk._weak_against)==WBd[1712]and pk._weak_against or type(pk.weak_against)==WBd[1712]and pk.weak_against or{})do
local vk=type(sk)==WBd[1712]and sk.damage_type or(type(sk)==WBd[623]and sk)or nil
if vk then
qk.weak[vk]=type(sk)==WBd[1712]and W.weakAmp(sk.amplification)or 1.5
end
end
for xk,yk in pairs(type(pk._strong_against)==WBd[1712]and pk._strong_against or type(pk.strong_against)==WBd[1712]and pk.strong_against or{})do
local zk=type(yk)==WBd[1712]and yk.damage_type or(type(yk)==WBd[623]and yk)or nil
local Ak,Bk=type(yk)==WBd[1712]and tonumber(yk.amplification),type(yk)==WBd[1712]and tonumber(yk.resistance)
if zk then
if Bk then
qk.res[zk]=100/(100+Bk)
elseif Ak and Ak<1 then
qk.res[zk]=Ak
else
qk.strong[zk]=true
end
end
end
return(next(qk.weak)or next(qk.strong)or next(qk.res))and qk or nil
end
function W.rulesMod(Ck)
