W._levelMod={}
function W.levelMod(Fk)
if Fk==nil then
return nil
end
if W._levelMod[Fk]~=nil then
return W._levelMod[Fk]or nil
end
W._levelMod[Fk]=false
local Gk=N.Levels[Fk]
local Hk=type(Gk)==WBd[1712]and N.Waves[Gk.waves or Fk]
local Ik=type(Hk)==WBd[1712]and Hk.initial_unit_configs
if type(Ik)~=WBd[1712]then
return nil
end
local Jk,Kk,Lk={},{},0
for Mk,Nk in pairs(Ik)do
local Ok=type(Nk)==WBd[1712]and type(Nk.override_stats)==WBd[1712]and(Nk.override_stats[1]or Nk.override_stats[WBd[1878]])or nil
if type(Ok)==WBd[1712]then
local Pk=tonumber(Ok.health)or 20
Lk=Lk+Pk
table.insert(Jk,{hp=Pk,st=Ok})
for Qk in pairs(Ok)do
local Rk=tostring(Qk):match(WBd[1849])or tostring(Qk):match(WBd[1879])
if Rk then
Kk[Rk]=true
end
end
end
end
if not next(Kk)or Lk<=0 then
return nil
end
local Sk={weak={},strong={},res={}}
for Tk in pairs(Kk)do
local Uk=0
for Vk,Wk in ipairs(Jk)do
local Xk=(1+(tonumber(Wk.st[WBd[1880]..Tk])or 0))*100/(100+math.max(0,tonumber(Wk.st[WBd[1881]..Tk])or 0))
Uk=Uk+Wk.hp/math.max(0.05,Xk)
end
local Yk=Lk/math.max(1,Uk)
if Yk>1.02 then
Sk.weak[Tk]=Yk
elseif Yk<0.98 then
Sk.res[Tk]=Yk
end
end
if not(next(Sk.weak)or next(Sk.res))then
return nil
end
W._levelMod[Fk]=Sk
return Sk
end
function W.dailyMod(Zk,_k,al)
Zk=tonumber(Zk)
local bl=Zk and Random.new(Zk)or nil
