for dl,el in pairs(_k or{})do
cl.weak[el]=bl and 1+bl:NextNumber(0.5,0.7)or 1.5
end
for fl,gl in pairs(al or{})do
if bl then
cl.res[gl]=100/(100+bl:NextNumber(100,150))
else
cl.strong[gl]=true
end
end
return cl
end
