function W.itemValue(kl,ll)
if O.remnantFocus and W.REMNANT_FOCUS[kl]then
return W.REMNANT_FOCUS[kl]*(ll or 1)
end
if P.goalItems[kl]then
local ml=ll or 1
local nl=math.min(ml,tonumber(P.goalNeed[kl])or ml)
return P.goalItems[kl]*nl+(N.ITEM_VALUE[kl]or N.ITEM_DEFAULT)*math.max(0,ml-nl)
end
if O.team and jb.itemWorth then
local ol,pl=pcall(jb.itemWorth,kl)
if ol and pl then
return pl*(ll or 1)
end
end
local ql=N.GS.ITEM_CAPS and N.GS.ITEM_CAPS[kl]
local rl=N.session()
local sl=0
pcall(function()
sl=rl.inventory:get_number_of_owned_item(kl)
end)
if ql and sl>=ql then
return 0
end
return(N.ITEM_VALUE[kl]or N.ITEM_DEFAULT)*(ll or 1)
