function W.rewardValue(tl)
local ul=0
for vl,wl in pairs((tl and tl._rewards)or{})do
if type(wl)==WBd[1712]then
ul=ul+(tonumber(wl.gem_reward)or 0)+(tonumber(wl.gold_reward)or 0)*N.GOLD_VALUE
local xl=U.list(wl.item)
local yl=1
if wl._item_multichoice and#xl>0 then
yl=math.min(1,(tonumber(wl._item_multichoice.min)or#xl)/ #xl)
end
for zl,Al in ipairs(xl)do
local Bl=tonumber(Al.amount)or((tonumber(Al.min_amount)or 1)+(tonumber(Al.max_amount)or tonumber(Al.min_amount)or 1))/2
local Cl=(tonumber(Al.chance)or 1)*(1-(tonumber(Al._zero_chance)or 0))
ul=ul+W.itemValue(Al.item_id,Bl)*Cl*yl
end
end
end
return ul
end
