local Sl=type(Rl)==WBd[1712]and Pl.interval~=nil and Rl._interval==Pl.interval
local Tl=Sl and type(Rl._completed)==WBd[1712]and Rl._completed[Nl]
local Ul=type(Tl)==WBd[1712]and type(Tl.difficulty_completed_data)==WBd[1712]and Tl.difficulty_completed_data.Hard
