if not(En and En.n>0)then
return
end
local Fn=math.max(1,bb.wave())
local Gn=En.n/Fn
local Hn
if#En.hpK>0 then
local In=table.clone(En.hpK)
table.sort(In)
Hn=In[math.floor(#In/2)+1]
end
local Jn=type(P.hunt.starfall)==WBd[1712]and P.hunt.starfall or{}
local Kn=(tonumber(Jn.runs)or 0)+1
local Ln=1/math.min(Kn,5)
P.hunt.starfall={runs=Kn,perWave=Jn.perWave and(Jn.perWave+(Gn-Jn.perWave)*Ln)or Gn,hpK=Hn and(Jn.hpK and(Jn.hpK+(Hn-Jn.hpK)*Ln)or Hn)or Jn.hpK,at=os.time()}
local Mn,Nn
for On in pairs(En.waves)do
Mn=math.min(Mn or On,On)
Nn=math.max(Nn or On,On)
end
F.log(1,WBd[1927],string.format(WBd[1928],En.n,Fn,Gn,tostring(Mn),tostring(Nn),Hn or 0))
return{n=En.n,waves=Fn,hpK=Hn and math.floor(Hn*100+0.5)/100 or nil}
end
