for jP,kP in ipairs(YO)do
table.insert(P.goals,{uuid=kP.uuid,from=kP.from,to=kP.to,ready=kP.ready,intoTeam=kP.intoTeam,unknown=kP.unknown,hidden=kP.hidden,tierRank=kP.tierRank,text=gb.text(kP),gain=kP.gain,runs=kP.runs,plans=kP.plans,items=kP.items,eats=kP.eats,scoreFrom=kP.scoreFrom,scoreTo=kP.scoreTo,pinned=kP.pinned})
if not kP.ready and(kP.pinned or(not iP and O.goals and not kP.unknown and(not kP.hidden or kP.intoTeam)and(kP.intoTeam or hP==0)and hP<2))then
hP=hP+1
for lP,mP in ipairs(kP.plans)do
