local nP=O.goalValue*(kP.intoTeam and 1 or 0.4)/(hP==1 and 1 or 2)/math.max(1,mP.farmNeed)
P.goalItems[mP.farm]=math.max(P.goalItems[mP.farm]or 0,nP)
P.goalNeed[mP.farm]=math.max(P.goalNeed[mP.farm]or 0,mP.farmNeed)
end
end
end
if#P.goals>=12 then
