function jb.gainXp(uR,vR)
local wR,xR=tonumber(uR.xp)or 0,jb.xpFor(uR.unit_id,jb.cap(uR))
local yR=math.max(0,xR-wR)
if yR<=0 or(vR or 0)<=0 then
return 0,0
end
local zR=math.min(vR,yR)
local AR=jb.base(uR)
if AR<=0 then
return 0,zR
end
return jb.share(uR.unit_id)*(jb.score(jb.whatIf(uR,{xp=wR+zR}))/AR-1)*100,zR
end
function jb.gainFuse(BR)
if jb.lb(BR)>=1 then
return 0
end
local CR=jb.base(BR)
if CR<=0 then
return 0
end
local DR=jb.whatIf(BR,{xp=math.max(tonumber(BR.xp)or 0,jb.xpFor(BR.unit_id,110)),further_modifiers={limit_break={current_limit_break=1}}})
return jb.share(BR.unit_id)*(jb.score(DR)/CR-1)*100+5
end
