function jb.relicWorth(ER,FR)
local GR=FR._unique_item_data and FR._unique_item_data._unique_relic_data
if not GR then
return 0
end
local HR=N.Items[FR.item_id]or{}
local IR,JR=V.types(ER.unit_id)
if HR.main_damage_type and HR.main_damage_type~=WBd[2428]and HR.main_damage_type~=JR then
return 0
end
local KR,LR=0,0
for MR,NR in pairs(GR._core_damage_type_buffs or{})do
if IR[NR.damage_type]then
KR=KR+(tonumber(NR.mul)or 0)+(tonumber(NR.add_upg)or 0)*0.01+(tonumber(NR.pen)or 0)*0.001
LR=LR+(tonumber(NR.crit)or 0)
end
end
KR=KR+LR*0.5
local OR=V.rows(ER.unit_id)
local PR=OR and OR[OR.max]
local QR=(PR and tonumber(PR.cd)or 0)*V.mult(ER,WBd[1875])
for RR,SR in pairs(GR._unique_relic_effects or{})do
local TR=type(SR.params)==WBd[1712]and SR.params or{}
if SR.id==WBd[2429]then
local UR=math.min(1,(tonumber(TR.extra_damage)or 0)*QR/math.max(1,tonumber(TR.time_interval)or 40))
local VR=V.DRONES and V.DRONES[ER.unit_id]
if VR and VR.late and QR>0 then
local WR=1/QR
UR=UR*WR/(WR+(tonumber(VR.max)or 0)*(tonumber(VR.late.dmg)or 0)*(tonumber(VR.hits)or 1)/math.max(0.1,tonumber(VR.late.cd)or 4))
end
KR=KR+UR
elseif SR.id==WBd[2430]then
KR=KR+(tonumber(TR.dmg_buff)or 0)*0.25
elseif SR.id==WBd[2431]then
KR=KR+(tonumber(TR.dmg_buff)or 0)*LR
elseif SR.id==WBd[2432]then
if IR.magic then
KR=0
else
KR=KR+(tonumber(TR.dmg_buff)or 0)*0.3
end
elseif SR.id==WBd[2433]then
if IR.water_damage then
KR=KR+0.05
end
end
end
return KR
end
function jb.relicPlan()
local XR=N.session()
if not XR then
return nil
end
local YR=XR.inventory and XR.inventory.inventory_profile_data or{}
local ZR={}
for _R,aS in ipairs(YR.unique_items or{})do
if type(aS)==WBd[1712]and aS.uuid and(N.Items[aS.item_id]or{}).item_group==WBd[2434]then
table.insert(ZR,aS)
end
end
local bS={}
for cS,dS in ipairs(V.equipped())do
local eS=dS.data and dS.data.rarity
if not V.isFarm(dS.id)and(eS==WBd[2004]or eS==WBd[2005]or eS==WBd[2413]or eS==WBd[2435])then
local fS=jb.share(dS.id)
if not P.str.share[dS.id]then
fS=math.min(fS,0.15)
end
local gS={}
for hS,iS in ipairs(ZR)do
local jS=jb.relicWorth(dS.u,iS)*fS*100
if jS>0.01 then
table.insert(gS,{it=iS,w=jS})
end
end
table.sort(gS,function(kS,lS)
if kS.w~=lS.w then
return kS.w>lS.w
end
return kS.it.uuid<lS.it.uuid
end)
local mS,nS={},{}
for oS,pS in ipairs(gS)do
local qS=nS[pS.it.item_id]or 0
if#mS<6 and qS<((N.Items[pS.it.item_id]or{}).unique_equip and 1 or 2)then
nS[pS.it.item_id]=qS+1
table.insert(mS,pS)
end
end
if dS.u._equipped_relic then
