local Kib=Bib.collection:get_unit_by_uuid(Jib)
if Kib then
Hib[Kib.unit_id]=Jib
end
end
for Lib,Mib in ipairs(O.dailyTeam)do
local Nib,Oib=Hib[Mib],nil
if not Nib then
local Pib,Qib=V.isFarm(Mib),V.rows(Mib)
for Rib,Sib in pairs(Bib.profile_data.collection.owned_units)do
if Sib.unit_id==Mib then
local Tib=Bib.collection:get_unit_by_uuid(Sib.uuid)or Sib
local Uib,Vib
if Pib then
Uib,Vib=pcall(V.farm,Tib,Qib and Qib.max or 0)
else
Uib,Vib=pcall(V.score,Tib)
end
Vib=Uib and Vib or 0
if not Oib or Vib>Oib then
Nib,Oib=Sib.uuid,Vib
end
end
end
end
if Nib then
table.insert(Gib,Nib)
end
end
if#Gib== #O.dailyTeam then
if P.train.on then
hb.home()
end
if not hb.same(hb.team(),Gib)then
