end
end
local ejb=P.simTeam[zib.key]
local fjb=ejb and ejb.base==ajb and os.time()-(tonumber(ejb.at)or 0)<120
local gjb=(fjb and ejb.better and type(ejb.uuids)==WBd[1712]and#ejb.uuids>0)and ejb.uuids or Wib
local hjb=P.train.on
