function eb.upgradeGain(Xlb,Ylb,Zlb,amb,bmb,cmb)
local dmb,emb=Ylb[Zlb],Ylb[Zlb+1]
local fmb=(dmb.cd>0 and dmb.damage/dmb.cd or 0)
local gmb=(emb.cd>0 and emb.damage/emb.cd or 0)*V.aoe(emb.atk,emb.range)/math.max(0.3,V.aoe(dmb.atk,dmb.range))
local hmb=fmb>0 and Xlb*(gmb/fmb-1)or(cmb or 0)
local imb=Ylb[Zlb+2]
if imb and Zlb+1<Ylb.max and imb.cd>0 and emb.cd>0 and fmb>0 then
local jmb=Xlb*((imb.damage/imb.cd)/fmb-1)
local kmb=amb+imb.cost*bmb
if jmb/kmb>hmb/amb then
hmb=hmb+(jmb/kmb*amb-hmb)*0.5
end
end
local lmb=(emb.range or 0)>(dmb.range or 0)and(1+((emb.range-dmb.range)/math.max(1,dmb.range)))or 1
return math.max(0,hmb)*lmb
end
function eb.dpsFor(mmb,nmb)
if nmb<=0 then
return 0
end
local omb={}
for pmb,qmb in ipairs(mmb)do
if not qmb.farm and qmb.gain>0 then
table.insert(omb,qmb)
end
end
table.sort(omb,function(rmb,smb)
return rmb.gain/rmb.cost>smb.gain/smb.cost
end)
local tmb,umb=0,0
for vmb,wmb in ipairs(omb)do
if nmb<=0 then
break
end
umb=wmb.gain/wmb.cost
local xmb=math.min(1,nmb/wmb.cost)
tmb=tmb+wmb.gain*xmb
nmb=nmb-wmb.cost*xmb
end
return tmb+math.max(0,nmb)*umb*0.7
end
function eb.shieldDps(ymb,zmb,Amb,Bmb,Cmb,Dmb,Emb)
if(Bmb or 0)<=0 or(ymb or 0)<=0 or(Cmb or 0)<=0 then
return ymb or 0
end
zmb,Amb,Dmb=math.max(0.3,zmb or 2),math.max(1,Amb or 1),Dmb or 1
local Fmb=ymb*Dmb*zmb/Amb
return Cmb*Amb/((Bmb/math.max(1,Emb or 1)+math.max(1,Cmb/Fmb))*zmb)/Dmb
end
function eb.shieldGain(Gmb,Hmb,Imb,Jmb,Kmb,Lmb,Mmb,Nmb)
local Omb,Pmb=V.attackInfo(Hmb.atk,Hmb.range),V.attackInfo(Jmb.atk,Jmb.range)
local Qmb=eb.shieldDps(Gmb,(tonumber(Hmb.cd)or 2)*(Mmb or 1),Omb.n,Kmb,Lmb,Nmb,Omb.hits)
local Rmb=eb.shieldDps(Imb,(tonumber(Jmb.cd)or 2)*(Mmb or 1),Pmb.n,Kmb,Lmb,Nmb,Pmb.hits)
local Smb=math.max(0,((tonumber(Jmb.range)or 0)-(tonumber(Hmb.range)or 0))/math.max(1,tonumber(Hmb.range)or 1))
return math.max(0,Rmb-Qmb)+Qmb*Smb
end
function eb.shieldWork(Tmb,Umb,Vmb,Wmb,Xmb,Ymb,Zmb,_mb,anb)
if(Wmb or 0)<=0 then
return 0
end
local bnb=3*Wmb*(Xmb or 1)/math.max(1,Ymb or 20)
if(Vmb or 0)>=bnb then
return 0
end
return math.max(1,Tmb or 1)*math.max(1,anb or 1)/math.max(0.3,Umb or 2)*math.min(Zmb or 0,_mb or 0)
end
function eb.holdGain(cnb,dnb,enb,fnb)
if not cnb or(dnb or 0)<=0 then
return 0
end
local gnb,hnb=tonumber(cnb.stun)or 0,tonumber(cnb.slowTime)or 0
if gnb<=0 and hnb<=0 then
return 0
end
local inb,jnb=gnb>0 and gnb or hnb,gnb>0 and 1 or(tonumber(cnb.slowPct)or 0.3)
local knb=jnb*inb/(inb+(tonumber(cnb.ccCd)or 8))
local lnb=knb/math.max(0.1,1-knb)
return dnb*lnb*U.clamp(enb or 0.5,0,1)*math.min(1,(tonumber(cnb.n)or 1)/2)/(1+(fnb or 0))
end
function eb.bleedGain(mnb,nnb,onb,pnb)
if(mnb or 0)<=0 then
return 0
end
local qnb=nnb or 0
for rnb,snb in ipairs(onb or{})do
qnb=math.max(qnb,(tonumber(snb.hp)or 0)*0.5)
