end
function eb.keepsUp(xnb,ynb,znb,Anb,Bnb)
local Cnb=xnb.coming
if not(Cnb and#Cnb>0 and xnb.waveSec)then
return true
end
local Dnb=xnb.eff or 1
local Enb=xnb.money-znb
local Fnb=(xnb.teamDps or 0)*(xnb.shieldK or 1)+(Anb or 0)*Dnb+eb.dpsFor(ynb,math.max(0,Enb))*Dnb
local Gnb=(xnb.farmNow or 0)+(Bnb or 0)
