fb.DMG_PRIOR_RUNS=6
function fb.dmgAll()
local qwb=fb._dmgAll
if qwb and os.clock()-qwb.t<60 then
return qwb.v
end
local rwb,swb={},{}
for twb,uwb in pairs(P.simCal)do
local vwb=twb~=WBd[1736]and not tostring(twb):find(WBd[3136],1,true)and type(uwb)==WBd[1712]and type(uwb.dmgK)==WBd[1712]and uwb.dmgK or nil
for wwb=1,#fb.DMG_BANDS do
local xwb=vwb and vwb[tostring(wwb)]
