fb.DMG_SOLVE_LO,fb.DMG_SOLVE_HI,fb.DMG_SOLVE_TRIES=0.1,3,6
function fb.dmgSolve(Uwb,Vwb,Wwb,Xwb,Ywb)
local function Zwb(_wb)
local axb=table.clone(Uwb)
axb.dmgMul,axb._dk=_wb,nil
local bxb,cxb=pcall(fb.runRaw,axb,Vwb,Wwb)
if not(bxb and type(cxb)==WBd[1712])then
return nil
end
if Ywb then
return cxb.won and 1 or-1
end
if cxb.won then
