local zKb=tonumber(qKb.alive[tostring(yKb)])
local AKb=uKb.aliveAt[yKb]
if zKb and AKb and zKb>0 then
vKb=vKb+zKb
wKb=wKb+AKb
xKb=xKb+1
end
end
if xKb<2 or wKb<=0 then
return nil
end
local BKb=vKb/wKb
return{ratio=BKb,ok=BKb>=0.75 and BKb<=1.33,waves=xKb}
end
fb.GROWN_LEVEL,fb.GROWN_MIN=50,6
function fb.grownKinds()
local CKb=N.session()
local DKb,EKb={},0
for FKb,GKb in pairs(CKb.profile_data.collection.owned_units)do
local HKb=GKb.unit_id
if not DKb[HKb]and N.Units[HKb]and not V.isFarm(HKb)and V.rows(HKb)and not V.hidden(HKb)then
local IKb,JKb=pcall(N.USC.calculate_level,HKb,tonumber(GKb.xp)or 0)
if IKb and(tonumber(JKb)or 0)>=fb.GROWN_LEVEL then
DKb[HKb]=true
EKb=EKb+1
end
end
end
return EKb
end
function fb.pool(KKb,LKb)
local MKb=N.session()
local NKb,OKb={},{}
local PKb=fb.grownKinds()>=fb.GROWN_MIN
for QKb,RKb in pairs(MKb.profile_data.collection.owned_units)do
local SKb=MKb.collection:get_unit_by_uuid(RKb.uuid)or RKb
local TKb,UKb=pcall(N.USC.calculate_level,SKb.unit_id,tonumber(SKb.xp)or 0)
local VKb=V.isFarm(SKb.unit_id)or not PKb or(TKb and(tonumber(UKb)or 0)>=fb.GROWN_LEVEL)
if N.Units[SKb.unit_id]and V.rows(SKb.unit_id)and not V.hidden(SKb.unit_id)and VKb then
local WKb=V.isFarm(SKb.unit_id)
local XKb,YKb=pcall(WKb and function()
return V.farm(SKb,V.rows(SKb.unit_id).max)
end or V.score,SKb,KKb)
YKb=(XKb and YKb or 0)*(WKb and 1 or V.skinMul(SKb,LKb and LKb.skinSet))
local ZKb=WKb and OKb or NKb
if not ZKb[SKb.unit_id]or YKb>ZKb[SKb.unit_id].sc then
ZKb[SKb.unit_id]={u=SKb,sc=YKb}
end
end
end
local _Kb,aLb={},{}
for bLb,cLb in pairs(NKb)do
table.insert(_Kb,cLb)
end
for dLb,eLb in pairs(OKb)do
table.insert(aLb,eLb)
end
table.sort(_Kb,function(fLb,gLb)
return fLb.sc>gLb.sc
end)
table.sort(aLb,function(hLb,iLb)
return hLb.sc>iLb.sc
end)
local jLb={}
for kLb=1,math.min(10,#_Kb)do
table.insert(jLb,_Kb[kLb].u)
end
local lLb,mLb={},{}
for nLb=11,#_Kb do
local oLb=V.rows(_Kb[nLb].u.unit_id)
for pLb=0,oLb.max do
if oLb[pLb]and oLb[pLb].atk and V.attackInfo(oLb[pLb].atk,oLb[pLb].range).dot>0 then
table.insert(pLb==0 and lLb or mLb,_Kb[nLb].u)
break
end
end
end
for qLb=1,math.min(4,#lLb)do
table.insert(jLb,lLb[qLb])
end
for rLb=1,math.min(2,#mLb)do
table.insert(jLb,mLb[rLb])
end
for sLb=1,math.min(3,#aLb)do
table.insert(jLb,aLb[sLb].u)
end
local tLb={}
for uLb=11,#_Kb do
local vLb=V.rows(_Kb[uLb].u.unit_id)[0]
local wLb=vLb and vLb.atk and V.attackInfo(vLb.atk,vLb.range)
if wLb and(wLb.slowTime>0 or wLb.stun>0)then
table.insert(tLb,_Kb[uLb].u)
end
end
for xLb=1,math.min(3,#tLb)do
table.insert(jLb,tLb[xLb])
end
for yLb=11,#_Kb do
local zLb=_Kb[yLb].u.unit_id
if V.allyBuff(zLb)or V.BLESS.by[zLb]or V.GALE[zLb]then
table.insert(jLb,_Kb[yLb].u)
end
end
if LKb and((LKb.flyChance or 0)>0 or LKb.mapFly or(LKb.shield or 0)>0)then
local ALb,BLb={},{}
for CLb=11,#_Kb do
local DLb=_Kb[CLb].u
local ELb=V.rows(DLb.unit_id)[0]
if V.airFrom(DLb.unit_id)==0 then
table.insert(ALb,DLb)
end
local FLb,GLb=tonumber(ELb and ELb.cd)or 0,tonumber((N.Units[DLb.unit_id]or{}).cost)or 0
if FLb>0 and GLb>0 and V.range(DLb,0)>=15 then
local HLb=V.attackInfo(ELb.atk,ELb.range)
table.insert(BLb,{u=DLb,v=HLb.n*HLb.hits/FLb/GLb*math.min(6,V.cap(DLb))})
end
end
table.sort(BLb,function(ILb,JLb)
return ILb.v>JLb.v
end)
for KLb=1,math.min(4,#ALb)do
table.insert(jLb,ALb[KLb])
end
for LLb=1,math.min(6,#BLb)do
table.insert(jLb,BLb[LLb].u)
end
end
local MLb,NLb={},{}
for OLb,PLb in ipairs(jLb)do
if not MLb[PLb]then
MLb[PLb]=true
table.insert(NLb,PLb)
end
end
NLb.rest={}
for QLb,RLb in ipairs(_Kb)do
if not MLb[RLb.u]then
table.insert(NLb.rest,RLb.u)
end
end
return NLb
end
function fb.objective(SLb)
if SLb.kscore then
return(tonumber(SLb.kills)or 0)+SLb.wave*0.01
end
return(SLb.won and 1000 or 0)+SLb.wave*10-(SLb.won and SLb.t/60 or((SLb.left or 1)*9-math.min(9,SLb.t/60)))
end
fb.LADDER={1,1.3,1.7,2.2,3,4,6,8,12,16,24}
function fb.cliff(TLb,ULb,VLb)
local WLb
for XLb,YLb in ipairs(fb.LADDER)do
WLb=fb.run(TLb,ULb,{hpMul=YLb,layout=VLb})
if not WLb.won then
return YLb,WLb
end
end
return fb.LADDER[#fb.LADDER],WLb
end
function fb.exam(ZLb,_Lb)
local aMb,bMb,cMb=fb.teamFrom(_Lb,ZLb.map),0,0
for dMb,eMb in ipairs(fb.LADDER)do
local fMb,gMb=0,0
for hMb,iMb in ipairs({0.92,1,1.08})do
local jMb=fb.run(ZLb,aMb,{hpMul=eMb*iMb})
if jMb.won then
fMb=fMb+1
end
gMb=gMb+jMb.wave
end
bMb,cMb=bMb+fMb,gMb/3
task.wait()
if fMb==0 then
break
end
end
return bMb,cMb
end
fb.ZONE_CLOSE,fb.ZONE_GAIN=1.3,20
function fb.zoneKey(kMb)
return tostring(kMb.key)..WBd[1837]..tostring(kMb.map)
end
function fb.zoneChoice(lMb,mMb,nMb,oMb)
if O.killZone==false or lMb.zone or bb.forcedWay()or(lMb.infinite and fb.unbound(lMb.ld))then
return false
end
local pMb=P.zoneRec[fb.zoneKey(lMb)]
local qMb=pMb and(pMb.style==WBd[3139]or(pMb.style==nil and pMb.zone==true))
if pMb and pMb.won then
return qMb==true,qMb and WBd[3200]or nil
end
if pMb and qMb then
return false,WBd[3201]
end
local rMb=P.modes[lMb.key]
local sMb=rMb and tonumber(rMb.streak)or 0
if not pMb and rMb and(tonumber(rMb.wins)or 0)>0 and sMb==0 and lMb.key~=WBd[2118]and lMb.key~=WBd[2114]then
return false
end
local tMb=pMb~=nil or sMb>0
local uMb=oMb and nMb<=1 or(not oMb and nMb<=fb.ZONE_CLOSE)
if not(tMb or uMb)then
return false
end
local vMb=table.clone(lMb)
vMb.zone=true
local function wMb(xMb)
local yMb=0
for zMb,AMb in ipairs({0.92,1,1.08})do
yMb=yMb+fb.objective(fb.run(xMb,mMb,{hpMul=nMb*AMb}))
end
return yMb/3
end
local BMb=wMb(vMb)-wMb(lMb)
if tMb and BMb> -fb.ZONE_GAIN then
return true,WBd[3202],BMb
end
if uMb and BMb>fb.ZONE_GAIN then
return true,string.format(WBd[3203],nMb),BMb
end
return false,nil,BMb
end
function fb.strength(CMb,DMb)
local EMb,FMb,GMb,HMb,IMb=fb.teamFrom(DMb,CMb.map),0,0,0,0
for JMb,KMb in ipairs(fb.LADDER)do
local LMb,MMb=0,0
for NMb,OMb in ipairs({0.92,1,1.08})do
local PMb=fb.run(CMb,EMb,{hpMul=KMb*OMb})
if PMb.won then
LMb=LMb+1
end
MMb=MMb+PMb.wave
end
FMb,IMb=FMb+LMb,MMb/3
if KMb==1 then
GMb,HMb=LMb,MMb/3
end
task.wait()
if LMb==0 then
break
end
end
return FMb,GMb,HMb,IMb
end
function fb.bestTeam(QMb,RMb,SMb,TMb)
local UMb=U.now()
TMb=TMb or 25
local VMb=table.clone(RMb)
local WMb,XMb=fb.cliff(QMb,fb.teamFrom(VMb,QMb.map))
local function YMb(ZMb)
local _Mb=0
for aNb,bNb in ipairs(ZMb)do
if V.isFarm(bNb.unit_id)then
_Mb=_Mb+1
end
end
return _Mb
end
local cNb=YMb(SMb)>0
local function dNb(eNb)
local fNb=0
for gNb,hNb in ipairs(eNb)do
if not V.isFarm(hNb.unit_id)and not V.allyBuff(hNb.unit_id)then
fNb=fNb+V.cap(hNb)
end
end
return fNb
end
local iNb
while#VMb<6 do
local jNb,kNb
local lNb=cNb and YMb(VMb)==0
for mNb,nNb in ipairs(SMb)do
local oNb=false
for pNb,qNb in ipairs(VMb)do
if qNb.unit_id==nNb.unit_id then
oNb=true
end
end
if not oNb and(not lNb or V.isFarm(nNb.unit_id))then
local rNb=table.clone(VMb)
table.insert(rNb,nNb)
local sNb=fb.run(QMb,fb.teamFrom(rNb,QMb.map),{hpMul=WMb})
local tNb=fb.objective(sNb)
if not kNb or tNb>kNb then
jNb,kNb,iNb=nNb,tNb,sNb
end
end
end
if not jNb then
break
end
table.insert(VMb,jNb)
end
if cNb and YMb(VMb)==0 then
local uNb,vNb
for wNb=1,#VMb do
for xNb,yNb in ipairs(SMb)do
if V.isFarm(yNb.unit_id)then
local zNb=table.clone(VMb)
zNb[wNb]=yNb
local ANb=fb.run(QMb,fb.teamFrom(zNb,QMb.map),{hpMul=WMb})
local BNb=fb.objective(ANb)
if not vNb or BNb>vNb then
uNb,vNb,iNb=zNb,BNb,ANb
end
end
end
end
if uNb then
VMb=uNb
end
end
local function CNb(DNb,ENb)
local FNb=fb.teamFrom(DNb,QMb.map)
return(fb.objective(ENb)+fb.objective(fb.run(QMb,FNb,{hpMul=WMb*0.92}))+fb.objective(fb.run(QMb,FNb,{hpMul=WMb*1.08})))/3
end
local GNb,HNb=iNb or XMb,CNb(VMb,iNb or XMb)
if type(SMb.rest)==WBd[1712]and#SMb.rest>0 then
local INb,JNb
for KNb,LNb in ipairs(VMb)do
if not V.isFarm(LNb.unit_id)and not V.allyBuff(LNb.unit_id)then
local MNb,NNb=pcall(V.score,LNb,QMb.mod)
NNb=(MNb and NNb or 0)*V.skinMul(LNb,QMb.skinSet)
if not JNb or NNb<JNb then
INb,JNb=KNb,NNb
end
end
end
if INb then
local ONb,PNb={},U.now()
for QNb,RNb in ipairs(SMb.rest)do
if U.now()-PNb>5 then
break
end
local SNb=false
for TNb,UNb in ipairs(VMb)do
if UNb.unit_id==RNb.unit_id then
SNb=true
end
end
if not SNb then
local VNb=table.clone(VMb)
VNb[INb]=RNb
table.insert(ONb,{u=RNb,o=fb.objective(fb.run(QMb,fb.teamFrom(VNb,QMb.map),{hpMul=WMb}))})
end
end
table.sort(ONb,function(WNb,XNb)
return WNb.o>XNb.o
end)
SMb=table.clone(SMb)
for YNb=1,math.min(4,#ONb)do
table.insert(SMb,1,ONb[YNb].u)
end
UMb=UMb+(U.now()-PNb)
end
end
for ZNb=1,2 do
local _Nb=false
for aOb=1,#VMb do
for bOb,cOb in ipairs(SMb)do
if U.now()-UMb>TMb then
return VMb,GNb,WMb,XMb
end
local dOb=false
for eOb,fOb in ipairs(VMb)do
if fOb.unit_id==cOb.unit_id then
dOb=true
end
end
if not dOb then
local gOb=table.clone(VMb)
gOb[aOb]=cOb
if(not cNb or YMb(gOb)>0)and dNb(gOb)>=math.min(8,dNb(VMb))then
local hOb=fb.run(QMb,fb.teamFrom(gOb,QMb.map),{hpMul=WMb})
local iOb=fb.objective(hOb)
if iOb>HNb+1 then
iOb=CNb(gOb,hOb)
if iOb>HNb+1 then
VMb,HNb,GNb,_Nb=gOb,iOb,hOb,true
end
end
end
end
end
end
if not _Nb then
break
end
end
return VMb,GNb,WMb,XMb
end
function fb.evolutions()
local jOb=N.session()
local kOb,lOb={},{}
local mOb=jOb.inventory
local function nOb(oOb)
