pcall(function()
pOb=mOb:get_number_of_owned_item(oOb)
end)
return pOb
end
for qOb,rOb in pairs(jOb.profile_data.collection.owned_units)do
local sOb=N.Units[rOb.unit_id]
if sOb and sOb.evolve and sOb.evolve.evolve_unit and not sOb.evolve.hide_from_ui and not lOb[rOb.unit_id]and N.Units[sOb.evolve.evolve_unit]then
lOb[rOb.unit_id]=true
local tOb=rOb.shiny and sOb.evolve.shiny or sOb.evolve.normal
if tOb then
local uOb={}
for vOb,wOb in pairs(tOb.item_requirement or{})do
if nOb(wOb.item_id)<(wOb.amount or 1)then
table.insert(uOb,string.format(WBd[2398],(N.Items[wOb.item_id]or{}).name or wOb.item_id,nOb(wOb.item_id),wOb.amount))
end
end
for xOb,yOb in pairs(tOb.unit_requirement or{})do
local zOb=0
for AOb,BOb in pairs(jOb.profile_data.collection.owned_units)do
if BOb.unit_id==yOb.unit_id and(not yOb.shiny or BOb.shiny)then
zOb=zOb+1
end
end
if zOb<(yOb.amount or 1)then
table.insert(uOb,string.format(WBd[2398],V.name(yOb.unit_id),zOb,yOb.amount))
end
end
local COb=gb.killsShort(jOb.collection:get_unit_by_uuid(rOb.uuid)or rOb,tOb)
if COb then
table.insert(uOb,string.format(WBd[2686],COb.what,U.fmt(COb.have),U.fmt(COb.need)))
end
if#uOb<=1 then
local DOb=jOb.collection:get_unit_by_uuid(rOb.uuid)or rOb
table.insert(kOb,{u=DOb,from=rOb.unit_id,to=sOb.evolve.evolve_unit,missing=uOb,evolved={unit_id=sOb.evolve.evolve_unit,uuid=WBd[2389]..tostring(DOb.uuid),xp=DOb.xp,traits=DOb.traits,trait_stats=DOb.trait_stats,further_modifiers=DOb.further_modifiers}})
end
end
end
end
return kOb
end
function fb.levelFor(EOb)
