if EOb.kind==WBd[1891]and P.live.daily and P.live.daily.ld then
return P.live.daily.ld,P.live.daily.challenge
end
if kb.is(EOb.level)and P.live.event and P.live.event.ld then
return P.live.event.ld,nil
end
if EOb.kind==WBd[1894]then
local GOb,HOb=pcall(W.tnRow,N.prof())
return GOb and type(HOb)==WBd[1712]and HOb.ldOverride or nil,nil
end
if EOb.kind==WBd[1893]then
