return IOb and JOb or nil,nil
end
local KOb=EOb.kind~=WBd[1726]or(FOb and type(FOb.ld)==WBd[1712]and FOb.ld.id==EOb.level and FOb.ch==EOb.challenge)
if FOb and type(FOb.ld)==WBd[1712]and KOb then
