MOb._difficulty=EOb.diff
MOb._gamemode=MOb._OVERRIDE_GAMEMODE or((EOb.kind==WBd[1750]or EOb.kind==WBd[1892])and WBd[1750])or(MOb.infinite and WBd[1731])or WBd[1749]
return MOb,nil
