function fb.typeWord(NOb)
local OOb,POb=pcall(N.data,WBd[3204])
local QOb=OOb and type(POb)==WBd[1712]and type(POb.TYPES)==WBd[1712]and POb.TYPES[tostring(NOb)]or nil
return(type(QOb)==WBd[1712]and type(QOb.name)==WBd[623]and QOb.name~=WBd[637]and QOb.name)or(tostring(NOb):gsub(WBd[3205],WBd[637]))
