function fb.against(ROb)
local SOb=fb.typeWord
local TOb={}
if not ROb then
return TOb
end
local UOb,VOb=pcall(fb.unbound,ROb.ld)
table.insert(TOb,(ROb.infinite and UOb and VOb)and WBd[3206]or string.format(WBd[3207],tonumber(ROb.total)or 0))
local WOb=ROb.mod or{}
local XOb,YOb,ZOb={},{},{}
for _Ob,aPb in pairs(WOb.weak or{})do
table.insert(XOb,{t=SOb(_Ob),v=tonumber(aPb)or 1})
end
table.sort(XOb,function(bPb,cPb)
return bPb.v>cPb.v
end)
for dPb,ePb in pairs(WOb.res or{})do
table.insert(YOb,string.format(WBd[3208],SOb(dPb),tonumber(ePb)or 1))
end
for fPb in pairs(WOb.strong or{})do
table.insert(ZOb,SOb(fPb))
end
if#XOb>0 then
local gPb={}
for hPb,iPb in ipairs(XOb)do
table.insert(gPb,string.format(WBd[3209],iPb.t,iPb.v))
end
table.insert(TOb,WBd[3210]..table.concat(gPb,WBd[1822]))
end
if#YOb>0 then
table.sort(YOb)
table.insert(TOb,WBd[3211]..table.concat(YOb,WBd[1822]))
end
if#ZOb>0 then
table.sort(ZOb)
table.insert(TOb,WBd[3212]..table.concat(ZOb,WBd[1822])..WBd[3213])
end
local jPb={}
for kPb,lPb in pairs(ROb.configs or{})do
local mPb=type(lPb)==WBd[1712]and N.Units[lPb.unit_id]
if type(mPb)==WBd[1712]then
for nPb,oPb in pairs(type(mPb.enemy_modifiers)==WBd[1712]and mPb.enemy_modifiers or{})do
if oPb then
jPb[nPb]=true
end
end
if fb.flies(mPb)then
jPb.Flying=true
end
if type(mPb.barrier)==WBd[1712]or(tonumber(mPb.shield)or 0)>0 then
jPb.Shield=true
end
end
end
if(ROb.flyChance or 0)>0 then
jPb.Flying=true
end
if ROb.armorAll then
jPb.Armor=true
end
if(ROb.shield or 0)>0 then
jPb.Shield=true
end
if(ROb.burstChance or 0)>0 then
jPb.Burst=true
end
local pPb={Flying=WBd[3214],Armor=WBd[3215],Ice=WBd[3216],Fire=WBd[1846],Soaring=WBd[3217],Burst=WBd[3218],Shield=WBd[3219]}
local qPb={}
for rPb in pairs(jPb)do
table.insert(qPb,pPb[rPb]or tostring(rPb):lower())
end
table.sort(qPb)
if#qPb>0 then
table.insert(TOb,WBd[3220]..table.concat(qPb,WBd[1822]))
end
if(ROb.red or 0)>0 then
table.insert(TOb,string.format(WBd[3221],math.floor(ROb.red*100+0.5)))
end
if(ROb.regen or 0)>0 then
table.insert(TOb,string.format(WBd[3222],tostring(math.floor(ROb.regen*1000+0.5)/10)))
end
local sPb=ROb.fx
if sPb then
local tPb,uPb={},{}
if math.abs((sPb.hp or 1)-1)>0.001 then
table.insert(tPb,string.format(WBd[3223],sPb.hp))
end
if math.abs((sPb.speed or 1)-1)>0.001 then
table.insert(tPb,string.format(WBd[3224],sPb.speed))
end
if(sPb.fly or 0)>0 then
table.insert(tPb,string.format(WBd[3225],math.floor(sPb.fly*100+0.5)))
end
if(sPb.shield or 0)>0 then
table.insert(tPb,string.format(WBd[3226],math.floor(sPb.shield+0.5)))
