if#HUb==0 then
CUb={none=true,sig=BUb,at=os.time()}
else
local IUb=fb.evaluate(GUb,fb.teamFrom(DUb,GUb.map))
CUb={p=IUb.p,wave=IUb.wave,won=IUb.won,total=GUb.total,margin=IUb.margin,sig=BUb,at=os.time(),zone=GUb.zone~=false or nil}
end
