local D2b=type(C2b)==WBd[1712]and(tonumber(C2b.highest_claimed_wave)or 0)>=A2b and os.time()-(tonumber(C2b.highest_claim_time)or 0)<900
if D2b then
P.infLive=true
end
F.log(1,WBd[2103],string.format(WBd[3501],A2b,D2b and WBd[3502]or WBd[3503]))
end)
end
function bb.infStop(E2b)
local F2b=0
for G2b,H2b in ipairs(U.list(N.GS.DAILY_INFINITE_REWARDS))do
F2b=math.max(F2b,tonumber(H2b.wave)or 0)
end
if F2b<=0 or E2b<=F2b+1 then
return
end
local I2b=P.train.on
if bb.trainee and I2b and I2b.have+(I2b.got or 0)+(bb.trainTk or 0)<I2b.need then
return
end
if not ab.every(WBd[3504],60)then
return
end
local J2b=W.rec(bb.key)
local K2b=tonumber(J2b.timed)or 0
local L2b=(K2b>0 and(J2b.sec or 0)>0)and math.max(0.5,((J2b.gems or 0)-200*K2b)/(J2b.sec/60))or 2.5
