for O2b,P2b in ipairs(M2b and W.lastScored or{})do
if P2b.kind~=WBd[1731]and(not N2b or(P2b.score or 0)>(N2b.score or 0))then
N2b=P2b
end
end
if not N2b or(N2b.score or 0)<=L2b then
return
end
bb.stopping=true
F.log(1,WBd[2103],string.format(WBd[3505],E2b,L2b,N2b.score,N2b.label))
bb.sellAll()
end
function bb.trainLeave(Q2b)
local R2b=P.train.on
if not(bb.infinite and bb.trainee and R2b)then
return
