end
local Tjc=bb.money()
local Ujc,Vjc=F.request(WBd[3641],WBd[3642],Ojc.uuid,N.Util.CFramePLV(Rjc,bb.lookAt(Rjc)))
if Ujc and Vjc then
bb.spent=bb.spent+(Ojc.data.cost or 0)
