F.log(1,WBd[3594],string.format(WBd[3644],V.name(Ojc.id),bb.spotKey(Rjc),Sjc,Pjc))
bb.placeLog=bb.placeLog or{}
table.insert(bb.placeLog,{t=math.floor(U.now()-(bb.startT or U.now())),w=bb.wave(),id=Ojc.id,x=math.floor(Rjc.X),z=math.floor(Rjc.Z),cover=math.floor((Sjc or 0)+0.5),why=tostring(Pjc):sub(1,90)})
