return true
end
if Tjc>=(Ojc.data.cost or 0)and bb.random then
bb.placeFail=bb.placeFail or{}
bb.placeFail[Ojc.uuid]=(bb.placeFail[Ojc.uuid]or 0)+1
if bb.placeFail[Ojc.uuid]>=2 then
bb.noSpot[Ojc.uuid]=3
F.log(1,WBd[3594],string.format(WBd[3646],V.name(Ojc.id),bb.fieldCount(),bb.FIELD_MAX))
end
end
if Ujc and Tjc>=(Ojc.data.cost or 0)and not bb.random then
local Wjc=bb.spotKey(Rjc)
bb.refused[Wjc]=true
local Xjc=bb.mapKey()
P.blocked[Xjc]=P.blocked[Xjc]or{}
if not bb.refusedRun[Wjc]then
