function bb.measure()
local fkc,gkc=bb.calRun,bb.info
if not(fkc and gkc)then
return
end
pcall(bb.sampleHelpers)
local hkc=U.now()
local ikc=bb.wave()
local jkc=bb.money()
if not fkc.start and jkc>0 and#bb.mine==0 then
fkc.start=jkc
end
if ikc~=fkc.lastW then
if bb.trialId and ikc>0 then
bb.trialTrace=bb.trialTrace or{}
local kkc,lkc,mkc,nkc=0,{},0,0
for okc,pkc in ipairs(bb.mine)do
local qkc=pkc._stats
if qkc.id.Value==bb.trialId then
kkc=kkc+1
table.insert(lkc,tostring(qkc.upgrade.Value))
elseif not V.isFarm(qkc.id.Value)then
nkc=nkc+1
