local tkc=0
for ukc,vkc in pairs(bb.helperDealt)do
if vkc.owner==bb.trialId then
tkc=tkc+vkc.v
end
end
table.insert(bb.trialTrace,string.format(WBd[3650],ikc,hkc-(bb.startT or hkc),jkc,table.concat(lkc,WBd[2423]),nkc,mkc+tkc,#(bb.enemies or{}),bb.hpAliveRaw or 0,bb.waveMax[ikc-1]or 0,bb.teamDps or 0))
end
