if fkc.paidT and ikc>0 and hkc-fkc.paidT<15 then
table.insert(fkc.skip,hkc-fkc.paidT)
end
fkc.paidT=nil
if ikc>0 then
fkc.alive[tostring(ikc)]=bb.hpAliveRaw or 0
end
fkc.lastW,fkc.lastWT=ikc,hkc
end
local wkc=workspace:FindFirstChild(WBd[3651])
if wkc and ikc>0 then
fkc.timer[tostring(ikc)]=math.max(fkc.timer[tostring(ikc)]or 0,tonumber(wkc.Value)or 0)
end
