function bb.holdGain(joc,koc)
if bb.random or not koc or not bb.info then
return 0
end
local loc=V.attackInfo(koc.atk,koc.range)
if(loc.stun or 0)<=0 and(loc.slowTime or 0)<=0 then
return 0
end
local moc=0
for noc,ooc in ipairs(bb.mine or{})do
local poc=ooc._stats
local qoc=V.rows(poc.id.Value)
local roc=qoc and qoc[math.min(poc.upgrade.Value,qoc.max)]
local soc=roc and roc.atk and V.attackInfo(roc.atk,roc.range)
if soc and((soc.stun or 0)>0 or(soc.slowTime or 0)>0)then
moc=moc+1
end
end
local toc,uoc=fb.mask(bb.info.map,V.range(joc.u,0)*(bb.info.rangeScale or 1)),0
for voc=1,fb.BINS do
if toc[voc]then
uoc=uoc+1
end
end
local woc=bb.depth and bb.depth.units>0 and bb.depth.covEnd or 1
local xoc=(V.airFrom(joc.id)==0)and 1 or(1-(1-N.FLY_GROUND)*math.min(1,bb.info.flyChance or 0))
return eb.holdGain(loc,bb.teamDps or 0,uoc/(math.max(0.1,woc)*fb.BINS)*xoc,moc)
end
function bb.buffGain(yoc)
local zoc=V.allyBuff(yoc.id)
if not zoc then
return 0
end
local Aoc=bb.buffShort(zoc)
local Boc=P.stack[zoc.attack]
local Coc=Boc and Boc.stacks and(Boc.cap or 1)or nil
local Doc,Eoc=pcall(V.range,yoc.u,0)
Eoc=(Doc and tonumber(Eoc)or 15)*((bb.info and tonumber(bb.info.rangeScale))or 1)
local Foc=Coc and O.community and tonumber(zoc.time)and tonumber(zoc.cd)
local function Goc(Hoc,Ioc)
local Joc=math.floor(Hoc*zoc.time/math.max(1,zoc.cd)+0.001)
return math.min(Coc,(1+Ioc)^Joc-1)
end
local Koc=0
for Loc,Moc in ipairs(Aoc)do
local Noc=0
for Ooc,Poc in ipairs(Aoc)do
if(Poc.pos-Moc.pos).Magnitude<=Eoc then
local Qoc=zoc.types[Poc.base]
local Roc=Qoc*zoc.uptime
if Foc then
local Soc,Toc=Goc(Poc.n,Qoc),Poc.n+1
while Toc<Poc.n+6 and Goc(Toc,Qoc)<=Soc+0.001 do
Toc=Toc+1
end
Roc=math.max(0,(Goc(Toc,Qoc)-Soc)/(Toc-Poc.n))
elseif Coc then
Roc=math.max(0,math.min(Coc,(Poc.n+1)*Qoc*zoc.uptime)-math.min(Coc,Poc.n*Qoc*zoc.uptime))
end
Noc=Noc+Poc.dps*Roc
end
end
Koc=math.max(Koc,Noc)
end
return Koc*(Foc and 1 or 0.7)
end
function bb.buffWanted(Uoc)
return bb.buffGain(Uoc)>0.01*(bb.teamDps or 0)
end
bb.summonHist={}
function bb.summonRate()
local Voc,Woc=U.now(),0
for Xoc,Yoc in pairs(bb.helperDealt)do
Woc=Woc+(tonumber(Yoc.v)or 0)
end
