local bpc,cpc=0,0
for dpc,epc in ipairs(bb.mine or{})do
local fpc=epc._stats.id.Value
if V.BLESS.by[fpc]then
bpc=bpc+1
end
if V.SUMMONER[fpc]then
cpc=cpc+bb.liveDps(epc,fpc)
end
end
if bpc>=V.BLESS.cap then
return 0
end
local gpc=math.max(bb.summonRate(),cpc*(1+V.BLESS.dmg*bpc))
return gpc/(1+V.BLESS.dmg*bpc)*V.BLESS.dmg
end
