function bb.buffRotation(grc,hrc,irc,jrc,krc,lrc)
if#bb.enemies==0 then
return false
end
local mrc=0
for nrc,orc in pairs(jrc.ally.types or{})do
mrc=math.max(mrc,tonumber(orc)or 0)
end
if mrc<=0 then
return false
end
local prc=tonumber(P.stack[irc].cap)or((1+mrc)^2-1)
local qrc=1
while qrc<6 and(1+mrc)^qrc-1<prc-0.02 do
qrc=qrc+1
end
local rrc=0
for trc,urc in ipairs(bb.mine)do
local vrc=urc._stats:FindFirstChild(WBd[1816])
if vrc and tostring(vrc.Value)==irc then
rrc=rrc+1
end
end
local wrc=V.allyBuff(hrc.id.Value)
local xrc=(wrc and tonumber(wrc.cd))or 60
local yrc=math.max(1,math.min(qrc,math.floor(rrc*krc/math.max(1,xrc)+0.001)))
local zrc=math.min(prc,(1+mrc)^yrc-1)
local Arc=krc/yrc
local Brc=grc:GetPivot().Position
local Crc,Drc=0,0
for Erc,Frc in ipairs(bb.mine)do
local Grc=Frc._stats
local Hrc=Grc.id.Value
if Frc~=grc and not V.isFarm(Hrc)and not V.allyBuff(Hrc)and(U.flat(Frc:GetPivot().Position)-U.flat(Brc)).Magnitude<=hrc.range.Value then
local Irc,Jrc=V.types(Hrc)
if jrc.ally.types[Jrc]then
Crc=Crc+1
if(tonumber(Grc:GetAttribute(WBd[3709]..tostring(Jrc)))or 0)<zrc-0.02 then
Drc=Drc+1
end
end
end
end
if Crc==0 or Drc==0 then
return false
end
bb.buffNext=bb.buffNext or{}
if lrc<(bb.buffNext[irc]or 0)then
return false
end
bb.buffNext[irc]=lrc+Arc
return true,string.format(WBd[3711],Drc,Crc,math.floor(zrc*100+0.5),yrc,rrc,Arc)
end
function bb.buffLevel(Krc)
local Lrc=0
for Mrc,Nrc in ipairs(bb.mine)do
local Orc=Nrc._stats
local Prc=Orc.id.Value
if not V.isFarm(Prc)and not V.allyBuff(Prc)then
local Qrc,Rrc=V.types(Prc)
local Src=Orc:FindFirstChild(WBd[3710])
if Src and not Krc then
Lrc=math.max(Lrc,tonumber(Src.Value)or 0)
end
if not Krc or Krc[Rrc]then
