local Tsc=Nsc.range.Value
local Usc,Vsc,Wsc
local Xsc=bb.trialId==Nsc.id.Value and P.trial and P.trial.study and#bb.enemies>0 and not bb.isGale(Nsc,tostring(Osc.Value))
if Xsc then
Usc,Vsc=true,WBd[3726]
elseif bb.isGale(Nsc,tostring(Osc.Value))then
Usc,Vsc=bb.gale(Msc,Nsc,tostring(Osc.Value),Ksc)
elseif Rsc.ally and P.stack[Osc.Value]and P.stack[Osc.Value].stacks and O.community then
Usc,Vsc=bb.buffRotation(Msc,Nsc,tostring(Osc.Value),Rsc,tonumber(Rsc.ally.time)or 30,Ksc)
elseif Rsc.ally or Rsc.allyCd or Rsc.allyRange then
