local Zsc=bb.buffedTill[Osc.Value]
if not Zsc then
Zsc=setmetatable({},{__mode=WBd[1926]})
bb.buffedTill[Osc.Value]=Zsc
end
local _sc,atc,btc,ctc={},0,0,0
for dtc,etc in ipairs(bb.mine)do
local ftc=etc._stats
local gtc=ftc.id.Value
if etc~=Msc and not V.isFarm(gtc)and not V.allyBuff(gtc)and(U.flat(etc:GetPivot().Position)-U.flat(Ssc)).Magnitude<=Tsc then
local htc,itc=V.types(gtc)
if not Rsc.ally or Rsc.ally.types[itc]then
table.insert(_sc,etc)
if ftc:FindFirstChild(WBd[3654])and ftc.target.Value~=nil then
local jtc=(Zsc[etc]or 0)>=Ksc
if Rsc.ally then
jtc=bb.buffOn(ftc,itc)or(Zsc[etc]or 0)-Ysc+2>=Ksc
end
if jtc then
btc=btc+1
ctc=math.max(ctc,Zsc[etc]or 0)
else
atc=atc+1
end
end
end
end
end
local ktc=P.stack[Osc.Value]
if ktc and not ktc.stacks and os.time()-(ktc.at or 0)>3*86400 then
ktc=nil
end
local ltc=Rsc.ally and btc>0 and bb.buffLevel(Rsc.ally.types)or 0
local mtc=btc>0 and Rsc.ally and O.community and ltc>0 and((ktc==nil and ctc-Ksc>5)or(ktc and ktc.stacks and ltc<(ktc.cap or 1)-0.02))
if atc>btc or mtc then
Usc,Vsc=true,string.format(WBd[3727],atc+btc)
if mtc and ktc==nil then
Wsc={key=Osc.Value,types=Rsc.ally.types,before=ltc}
Vsc=Vsc..string.format(WBd[3728],math.floor(ltc*100+0.5))
elseif mtc then
Vsc=Vsc..string.format(WBd[3729],math.floor(ltc*100+0.5))
end
for ntc,otc in ipairs(_sc)do
Zsc[otc]=Ksc+Ysc
end
end
elseif Rsc.baseSafe then
for ptc,qtc in ipairs(bb.enemies)do
