rtc=rtc+1
if utc.boss then
stc=true
end
end
end
local vtc=Ksc-bb.readySince[Msc]
local wtc=math.min(O.abilityHold*math.max(1,Psc.Value/60),Psc.Value*0.3)
local xtc=math.max(3,math.floor(#bb.enemies*0.3))
if bb.trialId==Nsc.id.Value and(tonumber((N.Units[bb.trialId]or{}).damage)or 0)<=0 and#bb.enemies>0 then
Usc,Vsc=true,WBd[3685]
elseif rtc>0 and stc then
Usc,Vsc=true,WBd[3731]
elseif rtc>=xtc then
Usc,Vsc=true,rtc..WBd[3732]
elseif rtc>=3 and vtc>=wtc*0.5 then
Usc,Vsc=true,string.format(WBd[3733],rtc,math.floor(vtc))
elseif rtc>=1 and vtc>=wtc then
Usc,Vsc=true,string.format(WBd[3734],math.floor(vtc),rtc)
