if#ztc.levels<12 then
table.insert(ztc.levels,math.floor(bb.buffLevel(Rsc.ally.types)*100+0.5))
end
end)
end
if Wsc then
task.wait(2)
local Atc=bb.buffLevel(Wsc.types)
local Btc=Atc>Wsc.before+0.05
P.stack[Wsc.key]={stacks=Btc,cap=Btc and 1 or nil,before=Wsc.before,after=Atc,at=os.time()}
F.log(1,WBd[3718],string.format(WBd[3739],V.name(Nsc.id.Value),Btc and WBd[3740]or WBd[3741],math.floor(Wsc.before*100+0.5),math.floor(Atc*100+0.5)))
F.saveSoon()
end
end
bb.activeBusy=false
end)
return
end
end
end
end
end
