function bb.huntChoose(wuc,xuc)
bb.fhP=bb.fhP or 1
local yuc=kb.floor()
local zuc=(bb.pressure or 0)>=O.safeReach or(bb.depth and bb.depth.leak)
local Auc=kb.weatherStrength(kb.weatherNow())
local Buc=table.find(kb.CARD_PICKS,O.huntCards)and O.huntCards or WBd[1993]
local Cuc,Duc,Euc,Fuc
local Guc={}
for Huc,Iuc in pairs(wuc)do
local Juc,Kuc=1,{}
for Luc,Muc in pairs(type(Iuc)==WBd[1712]and Iuc.effects or{})do
if type(Muc)==WBd[1712]then
local Nuc=bb.rogueEffect(Muc)
Juc=Juc*Nuc
table.insert(Kuc,bb.effectText(Muc))
end
end
if type(Iuc)==WBd[1712]and Iuc.weather then
Juc=Juc*kb.weatherStrength(Iuc.weather)/math.max(0.05,Auc)
end
local Ouc=type(Iuc)==WBd[1712]and kb.cardGems(Iuc,xuc)or 0
local Puc=Juc>=1 or(bb.fhP*Juc>=yuc and not zuc)
local Quc=math.log(math.max(0.05,Juc))
local Ruc=Quc*kb.STRENGTH_GEMS+(Puc and Ouc or-1000)
local Suc=kb.cardLuck(Iuc)
if Buc==WBd[639]and Puc and Suc>0 then
Ruc=2e6+Suc*1e4+Ouc
elseif Buc==WBd[1724]and Puc then
Ruc=1e6+kb.cardPearls(Iuc,xuc)*10+Ouc+Quc
elseif Buc==WBd[1997]then
Ruc=Quc*1e6+Ouc
end
if not Duc or Ruc>Duc then
Cuc,Duc,Euc,Fuc=Huc,Ruc,Juc,Ouc
end
table.insert(Guc,string.format(WBd[3754],tostring(Huc),tostring(type(Iuc)==WBd[1712]and Iuc.title or WBd[1984]),(type(Iuc)==WBd[1712]and Iuc.weather)and(WBd[2122]..tostring(Iuc.weather)..WBd[2096])or WBd[637],tostring(type(Iuc)==WBd[1712]and Iuc.option_type or WBd[1984]),Juc,math.floor(Ouc+0.5),table.concat(Kuc,WBd[2068])))
end
return Cuc,Euc,Fuc,Guc,yuc,zuc,Buc
end
function bb.huntPick(Tuc)
