if owc==WBd[3781]then
return math.max(0.5,1-pwc*0.5),0
end
if owc==WBd[3782]then
return math.max(0.5,1-pwc*0.2),0
end
if owc==WBd[3783]then
return 1+pwc*0.1,0
end
if owc==WBd[3784]then
return 1/math.max(0.3,1+pwc*0.5),0
end
if owc==WBd[3785]then
return math.max(0.5,1-pwc*0.1),0
end
if owc==WBd[3331]then
return 1/math.max(0.3,1+pwc),0
end
if owc==WBd[3337]then
return math.max(0.3,1-pwc*20),0
end
if owc==WBd[3338]then
return math.max(0.5,1-pwc*0.03),0
end
if owc==WBd[3786]then
