local dCc=math.max(0,(bb.total or 30)-cCc)
local eCc=bb.mergePlan
local fCc=bb.airLow()
local gCc,hCc,iCc
for jCc,kCc in ipairs(bb.mine)do
local lCc=kCc._stats
local mCc=lCc.id.Value
local nCc=N.Units[mCc]
local oCc=lCc:FindFirstChild(WBd[3847])and tonumber(lCc.total_spent.Value)or 0
if nCc and not nCc.unsellable and oCc>0 and not V.allyBuff(mCc)and not V.idol(mCc)and not(eCc and eCc.id==mCc)then
local pCc,qCc
if V.isFarm(mCc)then
local rCc=lCc:FindFirstChild(WBd[1818])and tonumber(lCc.farm_amount.Value)or 0
local sCc=rCc*dCc
if oCc>sCc*1.2 then
