local tCc,uCc=pcall(bb.liveDps,kCc,mCc)
uCc=tCc and uCc or math.huge
if oCc*bCc>3*uCc and uCc<0.1*(bb.teamDps or 0)then
pCc=oCc*bCc-uCc
qCc=string.format(WBd[3867],U.fmt(oCc))
end
end
if pCc and(not hCc or pCc>hCc)then
gCc,hCc,iCc=kCc,pCc,qCc
end
end
end
if not gCc then
