end
bb.spellBusy=true
task.spawn(function()
local vCc=V.name(gCc._stats.id.Value)
local wCc=F.request(WBd[3858],WBd[3859],YBc,gCc)
task.wait(1.5)
if wCc and(N.session().ingame_spells or{})[YBc]~=WBd[3851]then
bb.refunds=(bb.refunds or 0)+1
F.log(1,WBd[3843],string.format(WBd[3868],vCc,iCc))
F.status(WBd[3737],WBd[3869]..vCc)
else
