F.log(2,WBd[3843],WBd[3870]..vCc)
end
bb.spellBusy=false
end)
end
bb.BASE_WIN,bb.BASE_MARGIN,bb.BASE_SOON,bb.BASE_END=10,1.3,45,0.97
function bb.baseVerdict(xCc,yCc)
local zCc=(yCc.t or 0)-(xCc.t or 0)
if zCc<bb.BASE_WIN-1 then
return false
end
local ACc=((tonumber(xCc.base)or 0)-(tonumber(yCc.base)or 0))/zCc
if ACc<=0 or(tonumber(yCc.base)or 0)<=0 then
return false
end
local BCc=yCc.base/ACc
local CCc,DCc=0,0
local ECc,FCc=xCc.foes or{},yCc.foes or{}
for GCc,HCc in pairs(FCc)do
if HCc.prog>=bb.BASE_END then
CCc=CCc+HCc.hp
local ICc=ECc[GCc]
if ICc then
DCc=DCc+math.max(0,ICc.hp-HCc.hp)
end
end
end
for JCc,KCc in pairs(ECc)do
if KCc.prog>=bb.BASE_END and not FCc[JCc]then
DCc=DCc+KCc.hp
end
end
if CCc<=0 then
return false
end
local LCc=DCc/zCc
local MCc=LCc>0 and CCc/LCc or math.huge
local NCc={baseTime=BCc,loss=ACc,atEnd=CCc,rate=LCc,killTime=MCc}
return BCc<bb.BASE_SOON and MCc>BCc*bb.BASE_MARGIN,NCc
end
