bb.LEAK_WIN,bb.LEAK_SOON,bb.LEAK_MIN,bb.LEAK_MARGIN,bb.LEAK_AHEAD=3,12,3,1.5,6
function bb.leakAhead(aDc)
local bDc=0
local cDc=U.flat(aDc.pos)
for dDc,eDc in ipairs(bb.mine or{})do
local fDc=eDc:FindFirstChild(WBd[1773])
local gDc=fDc and fDc:FindFirstChild(WBd[3107])
local hDc=fDc and fDc:FindFirstChild(WBd[1877])
if gDc and hDc and not V.isFarm(gDc.Value)and not V.allyBuff(gDc.Value)then
local iDc,jDc=U.flat(eDc:GetPivot().Position),hDc.Value
if(not aDc.fly or bb.canAir(eDc))and(iDc-cDc).Magnitude>jDc then
for kDc,lDc in ipairs(bb.samples or{})do
if lDc.prog>aDc.prog and(U.flat(lDc.pos)-iDc).Magnitude<=jDc then
bDc=bDc+1
break
end
end
end
end
end
return bDc
end
function bb.leakStep(mDc)
if not mDc then
if bb.kind~=WBd[1732]or bb.bailed or O.bailOut==false or bb.random or bb.infinite then
return
end
end
local nDc=tostring(P.dg.room and P.dg.room.seed)
P.dg.bails=type(P.dg.bails)==WBd[1712]and P.dg.bails or{}
if not mDc and(tonumber(P.dg.bails[nDc])or 0)>=bb.BAIL_MAX then
return
end
local oDc=workspace:FindFirstChild(WBd[3871])and workspace._BASES:FindFirstChild(WBd[3493])
local pDc=oDc and oDc:FindFirstChild(WBd[3655])and oDc.base:FindFirstChild(WBd[3656])
local qDc=pDc and pDc:FindFirstChildOfClass(WBd[3515])
if not qDc or qDc.Health<=0 then
return
end
local rDc=(bb.info and tonumber(bb.info.baseRel))or fb.PRIOR.baseRel
local sDc=U.now()
bb.leakTrack=bb.leakTrack or{}
local tDc=bb.leakTrack
local uDc,vDc={},nil
for wDc,xDc in ipairs(bb.enemies or{})do
if xDc.m then
uDc[xDc.m]=true
local yDc,zDc=tonumber(xDc.hp)or 0,tonumber(xDc.prog)or 0
local ADc=tDc[xDc.m]
if not ADc then
tDc[xDc.m]={t=sDc,hp=yDc,prog=zDc}
else
if sDc-ADc.t>=bb.LEAK_WIN then
ADc.pace,ADc.net=(zDc-ADc.prog)/(sDc-ADc.t),(ADc.hp-yDc)/(sDc-ADc.t)
ADc.t,ADc.hp,ADc.prog=sDc,yDc,zDc
end
if ADc.pace and ADc.pace>0 and yDc>0 then
local BDc=(1-zDc)/ADc.pace
local CDc=math.max(0,ADc.net or 0)
local DDc=yDc-CDc*BDc
if DDc>0 and BDc<=bb.LEAK_SOON and BDc>=bb.LEAK_MIN then
local EDc=xDc.m:FindFirstChildOfClass(WBd[3515])
local FDc=qDc.Health/math.max(1,rDc*(EDc and EDc.MaxHealth or yDc))
local GDc=CDc>0 and DDc/CDc or math.huge
if GDc>FDc*bb.LEAK_MARGIN and(BDc<=bb.LEAK_AHEAD or bb.leakAhead(xDc)==0)and(not vDc or BDc<vDc.left)then
vDc={left=BDc,arriving=DDc,net=CDc,baseTime=FDc,hp=yDc}
end
end
end
end
end
end
for HDc in pairs(tDc)do
if not uDc[HDc]then
tDc[HDc]=nil
end
end
if mDc then
return vDc~=nil,vDc
end
if not vDc then
return
end
bb.bailNote(nDc)
F.log(1,WBd[2103],string.format(WBd[3874],bb.wave(),tonumber(bb.total)or 0,math.floor(vDc.left+0.5),U.fmt(vDc.hp),U.fmt(vDc.arriving),U.fmt(vDc.net),vDc.baseTime))
pcall(F.saveNow)
F.request(WBd[1781],WBd[3535])
end
bb.FOCUS_MAX=8
bb.coverMax=setmetatable({},{__mode=WBd[1926]})
function bb.allPast(IDc)
local JDc={}
for KDc,LDc in ipairs(bb.mine or{})do
local MDc=LDc._stats
local NDc=MDc.id.Value
if not V.isFarm(NDc)and not V.allyBuff(NDc)and MDc:FindFirstChild(WBd[1877])then
local ODc=tonumber(MDc.range.Value)or 0
local PDc=bb.coverMax[LDc]
if not(PDc and PDc.r==ODc)then
local QDc,RDc=U.flat(LDc:GetPivot().Position),-1
for SDc,TDc in ipairs(bb.samples or{})do
if TDc.prog>RDc and(U.flat(TDc.pos)-QDc).Magnitude<=ODc then
RDc=TDc.prog
end
end
PDc={r=ODc,far=RDc}
bb.coverMax[LDc]=PDc
end
table.insert(JDc,{far=PDc.far,air=bb.canAir(LDc)})
end
end
if#JDc==0 then
return false
end
for UDc,VDc in ipairs(IDc)do
for WDc,XDc in ipairs(JDc)do
if(not VDc.fly or XDc.air)and XDc.far>=(tonumber(VDc.prog)or 0)then
return false
end
end
end
return true
end
function bb.bossStep()
bb.focus=nil
if bb.random or bb.infinite or not(bb.total and bb.wave()>=bb.total)then
return
end
local YDc=bb.enemies or{}
for ZDc,_Dc in ipairs(YDc)do
local aEc=_Dc.m and _Dc.m:FindFirstChildOfClass(WBd[3515])
if aEc and aEc.MaxHealth>((bb.bossTop and bb.bossTop.hp)or 0)then
local bEc=_Dc.m:FindFirstChild(WBd[1773])
bb.bossTop={hp=aEc.MaxHealth,id=bEc and bEc:FindFirstChild(WBd[3107])and bEc.id.Value,regen=bEc and bEc:FindFirstChild(WBd[3875])and bEc.Regen.Value}
end
end
if#YDc<=2 and bb.bossTop and not bb.bossSaid then
bb.bossSaid=true
pcall(function()
local cEc=0
if bb.info then
for dEc,eEc in ipairs((fb.wave(bb.info,bb.total)))do
if eEc.boss and eEc.hp>cEc then
cEc=eEc.hp
end
end
end
F.log(1,WBd[2103],string.format(WBd[3876],tostring(bb.bossTop.id),bb.bossTop.hp,tostring(bb.bossTop.regen),cEc))
end)
end
local fEc= #YDc>2 and#YDc<=bb.FOCUS_MAX and bb.allPast(YDc)
if#YDc==0 or(#YDc>2 and not fEc)then
bb.focusTrack=nil
return
end
if fEc and not bb.allPastSaid then
bb.allPastSaid=true
F.log(1,WBd[2103],string.format(WBd[3877],#YDc))
end
local gEc,hEc=nil,1
for iEc,jEc in ipairs(YDc)do
if not gEc or jEc.hp>gEc.hp then
gEc=jEc
end
hEc=math.min(hEc,jEc.prog)
end
bb.focus={pos=gEc.pos,prog=gEc.prog,fly=gEc.fly,m=gEc.m}
local kEc=U.now()
local lEc=bb.focusTrack
if not lEc or lEc.m~=gEc.m then
bb.focusTrack={m=gEc.m,t=kEc,hp=gEc.hp,prog=gEc.prog}
return
end
if kEc-lEc.t>=10 then
lEc.net,lEc.rate=(lEc.hp-gEc.hp)/(kEc-lEc.t),(gEc.prog-lEc.prog)/(kEc-lEc.t)
lEc.t,lEc.hp,lEc.prog=kEc,gEc.hp,gEc.prog
end
if not lEc.rate or lEc.rate<=0 then
return
end
