function mb.evoNeeds(qed)
local sed=mb.K
local ted,ued,ved,wed={},{},{},{}
local function xed(yed)
yed=tonumber(yed)or 0
return yed>=10 and tostring(math.floor(yed+0.5))or string.format(WBd[4698],yed)
end
for zed,Aed in ipairs(qed.plans or{})do
local Bed,Ced=tonumber(Aed.have)or 0,tonumber(Aed.need)or 0
if Aed.takedown then
table.insert(ted,{mb.cap(tostring(Aed.what or WBd[2307])),string.format(WBd[4699],sed.comma(Bed),sed.comma(Ced)),p=Aed})
elseif Aed.copies then
wed[Aed.copies]=true
table.insert(ted,{WBd[4700]..V.name(Aed.copies),string.format(WBd[4701],Bed,Ced),p=Aed})
elseif Aed.item then
ved[Aed.item]=true
local Ded=(N.Items[Aed.item]or{}).name or tostring(Aed.item)
local Eed
if Aed.unknown then
Eed=WBd[4702]
elseif Aed.portal then
local Fed=W.PORTALS[Aed.portal]
Eed=string.format(WBd[4703],(N.Items[Aed.portal]or{}).name or tostring(Aed.portal),#W.portalsHeld(Aed.portal),Fed and(WBd[4704]..W.levelName(Fed.from)..WBd[4705])or WBd[637])
elseif Aed.eventShop then
Eed=string.format(WBd[4706],sed.comma(N.cur(Aed.currency)),sed.comma(Aed.cost),tostring(Aed.currency))
elseif Aed.shopKey then
Eed=string.format(WBd[4707],sed.comma(gb.have(Aed.costItem)),sed.comma((tonumber(Aed.cost)or 0)*(Ced-Bed)),(N.Items[Aed.costItem]or{}).name or tostring(Aed.costItem))
else
local Ged=Aed.best or(Aed.levels and Aed.levels[1])
local Hed=Ged and(tonumber(Ged.per)or 0)>0 and math.ceil((Ced-Bed)/Ged.per)or nil
Eed=Ged and string.format(WBd[4708],W.levelName(Ged.level),xed(Ged.per),Hed and string.format(WBd[4709],Hed)or WBd[637])or WBd[4702]
end
table.insert(ted,{Ded,string.format(WBd[4710],sed.comma(Bed),sed.comma(Ced),Eed),p=Aed})
end
end
for Ied,Jed in ipairs(qed.items or{})do
if not ved[Jed.id]then
table.insert(ued,string.format(WBd[4711],(N.Items[Jed.id]or{}).name or tostring(Jed.id),sed.comma(gb.have(Jed.id)),sed.comma(Jed.amount)))
end
end
for Ked,Led in ipairs(qed.eats or{})do
if not wed[Led.id]then
table.insert(ued,string.format(WBd[4712],V.name(Led.id),Led.amount,Led.amount))
end
end
local Med=ted[1]
return ted,ued,Med and(Med[1]..WBd[2056]..(Med[2]:match(WBd[4713])or Med[2]))or WBd[4714]
end
function mb.evoProgress(Ned)
if Ned.ready then
return 1
end
local Oed,Ped,Qed=0,0,{}
for Red,Sed in ipairs(Ned.plans or{})do
local Ted=tonumber(Sed.need)or 0
if Sed.item then
Qed[Sed.item]=true
end
if Ted>0 then
Oed=Oed+math.min(1,(tonumber(Sed.have)or 0)/Ted)
Ped=Ped+1
end
end
for Ued,Ved in ipairs(Ned.items or{})do
if not Qed[Ved.id]then
Oed=Oed+1
Ped=Ped+1
end
end
return Ped>0 and Oed/Ped or 0
end
function mb.pickFor(Wed)
Wed=tostring(Wed or WBd[637])
if Wed==WBd[637]then
return nil
end
local Xed=Wed:gsub(WBd[2908],WBd[2909])
for Yed,Zed in ipairs({{WBd[4214],WBd[4209],WBd[4214]},{WBd[1750],WBd[4207],WBd[1728]},{WBd[1731],WBd[4210],WBd[1731]},{WBd[1749],WBd[4208],WBd[1749]}})do
local _ed,afd=pcall(mb.modeOptions,Zed[1])
local bfd
for cfd,dfd in ipairs(_ed and afd or{})do
local efd=tostring(dfd.value)
if efd==WBd[2131]..Wed or efd==WBd[1884]..Wed or efd:find(WBd[4715]..Xed..WBd[1837])then
if not bfd or efd:find(WBd[4716])then
bfd=dfd
end
end
end
if bfd then
return{cfgKey=Zed[2],value=bfd.value,kind=Zed[1],kindKey=Zed[3],name=tostring(bfd.text)}
end
end
end
function mb.portalFor(ffd)
for gfd,hfd in ipairs(W.portalKinds())do
if table.find(hfd.levels or{},ffd)then
if#W.portalsHeld(hfd.pid)>0 then
return{cfgKey=WBd[4211],value=hfd.pid,kind=WBd[1895],kindKey=WBd[1902],name=tostring(hfd.name)}
end
local ifd=W.PORTALS[hfd.pid]
local jfd=ifd and ifd.from and mb.pickFor(ifd.from)
if jfd then
return jfd
end
end
end
end
function mb.evoMap(kfd)
local lfd=mb._evoMap
if lfd and lfd.uuid==kfd.uuid and U.now()-lfd.at<30 then
return lfd.m
end
local mfd
for nfd,ofd in ipairs(kfd.plans or{})do
if mfd then
break
end
if ofd.portal then
if#W.portalsHeld(ofd.portal)>0 then
mfd={cfgKey=WBd[4211],value=ofd.portal,kind=WBd[1895],kindKey=WBd[1902],name=(N.Items[ofd.portal]or{}).name or tostring(ofd.portal)}
end
elseif ofd.item and not ofd.unknown and not ofd.eventShop then
local pfd=ofd.best or(ofd.levels and ofd.levels[1])
if pfd and pfd.level then
mfd=mb.pickFor(pfd.level)or mb.portalFor(pfd.level)
end
end
end
mb._evoMap={uuid=kfd.uuid,at=U.now(),m=mfd}
return mfd
end
function mb.selectMap(qfd)
if not qfd then
return
end
O[qfd.cfgKey]=qfd.value
for rfd,sfd in ipairs(mb.modeKinds())do
if sfd.key==qfd.kindKey then
for tfd,ufd in ipairs(sfd.allow)do
O[ufd]=true
end
end
end
F.saveSoon()
W.lastScored=nil
ab.last.pick=nil
pcall(function()
mb.UI[qfd.cfgKey..WBd[4348]].Refresh(mb.modeOptions(qfd.kind),qfd.value)
end)
pcall(function()
mb.modeSw[qfd.kindKey].Set(true,true)
end)
pcall(mb.modeDeps,qfd.kindKey)
mb._evoMap=nil
F.log(1,WBd[2059],string.format(WBd[4717],qfd.name,mb.KIND_NAMES[qfd.kind]or qfd.kind))
mb.notify(WBd[4718],string.format(WBd[4719],qfd.name,mb.KIND_NAMES[qfd.kind]or qfd.kind),WBd[2355])
end
function mb.evoTarget()
local vfd=mb.focusNow()
local wfd=vfd~=WBd[637]and vfd or((P.train.on and P.train.on.uuid)or((P.goals or{})[1]and P.goals[1].uuid))
if not wfd then
return nil,vfd~=WBd[637]
end
for xfd,yfd in ipairs(P.goals or{})do
if yfd.uuid==wfd then
return yfd,vfd~=WBd[637]
end
end
for zfd,Afd in ipairs(P.goalsTop or{})do
if Afd.uuid==wfd then
return Afd,vfd~=WBd[637]
end
