function mb.sumHave(Aid)
if not Aid then
return nil
end
local Bid,Cid=pcall(N.cur,Aid)
return Bid and tonumber(Cid)or nil
end
function mb.sumRange(Did,Eid)
local Fid=Did.step*10
return 0,math.max(Did.max,math.ceil(((tonumber(Eid)or 0)*1.25)/Fid)*Fid),Did.step
end
function mb.inTime(Gid)
local Hid=math.max(0,math.floor((tonumber(Gid)or 0)-os.time()))
if Hid<60 then
return WBd[4906]
end
local Iid,Jid=math.floor(Hid/3600),math.floor(Hid%3600/60)
return WBd[4907]..(Iid>0 and string.format(WBd[2907],Iid,Jid)or string.format(WBd[2090],Jid))
end
function mb.sumBack(Kid)
local Lid=F.req and F.req.back and F.req.back[Kid]
if Lid and U.now()<Lid then
return os.time()+math.floor(Lid-U.now())
end
end
function mb.andList(Mid)
if#Mid<=1 then
return Mid[1]or WBd[637]
end
return table.concat(Mid,WBd[1822],1,#Mid-1)..WBd[2009]..Mid[#Mid]
end
function mb.sumTarget()
local Nid=mb.K
local Oid=P.snipe or{}
