end
Qid.stale=ab.snipeStale()
Qid.bid=ab.snipeWhere(Pid)
local Rid=Qid.bid and ab.snipeCost(Qid.bid)or nil
if Rid then
Qid.bc=Rid
Qid.have,Qid.keep,Qid.cost10=tonumber(Rid.have())or 0,tonumber(Rid.keep)or 0,(tonumber(Rid.cost)or 0)*10
Qid.avail=math.max(0,Qid.have-Qid.keep)
end
local Sid=mb.sumBack(WBd[2480])
