Qid.state,Qid.line,Qid.short=WBd[4912],Uid,WBd[4913]..Vid
end
if not O.snipeOn then
Qid.state,Qid.line,Qid.short=WBd[640],WBd[4914]..Qid.name..WBd[2016],WBd[640]
elseif P.pauseAll then
Qid.state,Qid.line,Qid.short=WBd[2928],WBd[4915],WBd[2928]
elseif not Oid.lookAt then
Tid(WBd[4916],WBd[4917])
elseif Qid.stale then
Tid(WBd[4918],WBd[4919])
elseif not Qid.bid then
Tid(string.format(WBd[4920],Qid.name,os.date(WBd[2513],Qid.turnAt)),string.format(WBd[4921],Qid.name,os.date(WBd[2513],Qid.turnAt)))
elseif not Rid then
Tid(WBd[4922],WBd[4923])
elseif not ab.watchRoom()then
Tid(WBd[4924],WBd[4925])
elseif Sid then
Tid(string.format(WBd[4926],os.date(WBd[2513],Sid)),WBd[4927])
elseif Qid.have-Qid.cost10<Qid.keep then
Tid(string.format(WBd[4928],Nid.comma(Qid.have),Rid.name,Nid.comma(Qid.cost10),Nid.comma(Qid.keep)),Rid.name..WBd[2836])
else
