function mb.sumPart(djd)
local ejd=tostring(Q.Summon or WBd[637])
for fjd in(ejd..WBd[1941]):gmatch(WBd[4430])do
if fjd:lower():sub(1,#djd)==djd:lower()then
return(fjd:sub(#djd+1):gsub(WBd[4942],WBd[637]))
end
end
end
function mb.sumGot(gjd,hjd)
local ijd,jjd,kjd={},{},{}
for ljd,mjd in ipairs(hjd or{})do
local njd=tostring((N.Units[mjd]or{}).rarity or WBd[2005])
jjd[njd]=(jjd[njd]or 0)+1
table.insert(ijd,V.name(mjd)..WBd[2122]..njd..WBd[2096])
end
for ojd,pjd in ipairs(mb.RARITY_ORDER)do
kjd[pjd]=true
local qjd=(tonumber((gjd or{})[pjd])or 0)-(jjd[pjd]or 0)
if qjd>0 then
table.insert(ijd,qjd..WBd[1883]..pjd)
end
end
for rjd,sjd in pairs(gjd or{})do
if not kjd[rjd]and(tonumber(sjd)or 0)>0 then
table.insert(ijd,sjd..WBd[1883]..tostring(rjd))
end
end
return mb.andList(ijd)
end
function mb.sumRecent()
local tjd=mb.K
local ujd=P.pulls or{}
local vjd=os.time()-86400
local wjd,xjd,yjd,zjd,Ajd=0,{},{},{},{}
local function Bjd(Cjd,Djd)
Cjd=tostring(Cjd or WBd[1984])
if not xjd[Cjd]then
table.insert(yjd,Cjd)
end
xjd[Cjd]=(xjd[Cjd]or 0)+(tonumber(Djd)or 0)
end
for Ejd,Fjd in ipairs(ujd)do
if(tonumber(Fjd.at)or 0)>=vjd then
wjd=wjd+(tonumber(Fjd.n)or 10)
Bjd(Fjd.cur,Fjd.cost)
for Gjd,Hjd in pairs(Fjd.got or{})do
zjd[Gjd]=(zjd[Gjd]or 0)+(tonumber(Hjd)or 0)
end
for Ijd,Jjd in ipairs(Fjd.best or{})do
table.insert(Ajd,Jjd)
end
end
end
if#ujd==0 then
for Kjd,Ljd in ipairs(P.spend or{})do
if(tonumber(Ljd.at)or 0)>=vjd and tostring(Ljd.what):find(WBd[1795])then
wjd=wjd+10
Bjd(Ljd.cur,Ljd.cost)
end
end
end
local Mjd
if wjd==0 then
Mjd= #ujd==0 and WBd[4943]or WBd[4944]
else
local Njd={}
for Ojd,Pjd in ipairs(yjd)do
table.insert(Njd,tjd.comma(xjd[Pjd])..WBd[1883]..Pjd)
end
Mjd=string.format(WBd[4945],tjd.comma(wjd),mb.andList(Njd))
local Qjd=mb.sumGot(zjd,Ajd)
if Qjd~=WBd[637]then
Mjd=Mjd..WBd[4946]..Qjd..WBd[2016]
end
end
local Rjd={}
for Sjd=1,math.min(20,#ujd)do
local Tjd=ujd[Sjd]
local Ujd=mb.sumGot(Tjd.got,Tjd.best)
table.insert(Rjd,string.format(WBd[4947],os.date(WBd[1812],tonumber(Tjd.at)or os.time()),ab.BANNER_NAME[Tjd.banner]or tostring(Tjd.banner),tostring(Tjd.rule or WBd[1796]),tjd.comma(tonumber(Tjd.cost)or 0),tostring(Tjd.cur or WBd[637]),Ujd~=WBd[637]and(WBd[2056]..Ujd)or WBd[637]))
end
return Mjd,#Rjd>0 and table.concat(Rjd,WBd[1722])or WBd[4831]
end
